package com.xiahu.reader;
import android.app.*;import android.os.*;import android.net.Uri;import android.content.*;import org.json.*;
public final class AboutTest extends Instrumentation{
 static void check(boolean v,String n){if(!v)throw new AssertionError(n);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;try{Context c=getTargetContext();JSONObject info=ProjectInfo.info(c);check(info.getString("version").equals("0.7.1")&&info.getInt("versionCode")==13,"Version read from actual APK");check(info.getString("repository").equals("https://github.com/XiaHusuper/light-novel-library"),"Own project URL");JSONObject notices=ProjectInfo.notices(c);check(notices.getJSONArray("items").length()==8,"Offline license entries");String all=notices.toString();check(all.contains("MewX")&&all.contains("Wenku8_Flutter")&&all.contains("Version 2, June 1991")&&all.contains("Version 3, 29 June 2007")&&all.contains("Apache License"),"Original upstream names and license texts present");for(String page:new String[]{"latest","changelog","repository"}){Uri uri=ProjectInfo.page(page);check(uri.getScheme().equals("https")&&uri.getHost().equals("github.com")&&uri.getPath().equals("/login"),"Only GitHub login opens");String suffix=page.equals("latest")?"/releases/latest":page.equals("changelog")?"/releases":"";check(uri.getQueryParameter("return_to").equals("/XiaHusuper/light-novel-library"+suffix),"Private destination preserved");check(uri.getQueryParameter("token")==null,"No repository credential in URL");}boolean rejected=false;try{ProjectInfo.page("https://example.invalid/");}catch(Exception e){rejected=true;}check(rejected,"Unrecognized destinations refused");out.putString("report",new JSONObject().put("passed",true).put("actualApkVersion",true).put("privateGitHubLoginDestinations",true).put("noRepositoryCredentialsInUrl",true).put("originalUpstreamNoticesOffline",true).put("unknownPageRejected",true).put("networkCalls",0).toString());ok=true;}catch(Throwable e){out.putString("failure",e.toString());}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
